            readonly api_reference?: string;
            /** @description Whether this server serves the dashboards. False in a build that leaves them out and where core.dashboards.enabled is off, and then the home page is the printer list. */
            readonly dashboards: boolean;
            /** @description The catalogue the page falls back to when the browser asks for one this app does not ship. */
            default_language: string;
            /** @description Whether this server serves the diagnostics bundle. False in a build that leaves it out, where core.diagnostics.enabled is off, and on an install with open access that does not switch it on; then the app hides the download. */
            readonly diagnostics: boolean;
            /** @description Where the browser sends the diagnostics bundle. Absent when core.diagnostics.send_url is empty. */
            diagnostics_send_url?: string;
