            object_count?: number;
            /** @description The objects of the print that can be cancelled one by one, ordered by id. It holds at most 256. When the machine reported more, every cancelled object is kept before the others, so an object missing from the list was not cancelled unless more than 256 were. */
            objects?: components["schemas"]["JobObject"][] | null;
